#include <stdio.h>
#include <stdint.h>
int main(void)
{
    // unsigned char attr; // unsigned char는 8비트 부호 없는 정수형 자료형으로, 0부터 255까지의 값을 저장할 수 있음
    uint8_t attr; // uint8_t는 C99 표준에서 정의된 8비트 부호 없는 정수형 자료형 // 명확하게 8비트 크기를 가지는 정수형을 사용하기 위해 uint8_t를 사용 
    attr = attr ^ attr; // attr의 값을 자기 자신과 XOR 연산하여 0으로 초기화 // XOR 연산은 두 비트가 다를 때 1을 반환하고, 같을 때 0을 반환하는 연산자 // attr이 어떤 값이든지 간에 attr ^ attr은 항상 0이 됨
    attr = attr | 0b00000001; // attr의 첫 번째 비트를 1로 설정하여 0b00000001이 됨 // 
    printf("attr: 0x%02x\n", attr); // attr의 값을 16진수 형식으로 출력 // %02x는 2자리 16진수로 출력하는 서식 지정자 // 
    attr = attr | (0b00000010 + 0b00000100); // attr의 두 번째와 세 번째 비트를 1로 설정하여 0b00000110이 됨 //0b는 2진수 리터럴을 나타내는 접두사 // 0b00000010은 두 번째 비트를 1로 설정하는 값이고, 0b00000100은 세 번째 비트를 1로 설정하는 값임 // 두 값을 더하면 0b00000110이 되어 attr의 두 번째와 세 번째 비트가 모두 1로 설정됨
    printf("attr: 0x%02x\n", attr); // attr의 값을 16진수 형식으로 출력 // attr의 값은 0b00000111이므로 0x07로 출력됨
    attr = attr & (~0b00000001); // attr의 첫 번째 비트를 0으로 설정하여 0b00000110이 됨 // ~ 연산자는 비트 NOT 연산자로, 0b00000001의 모든 비트를 반전시켜 0b11111110이 됨 // attr과 0b11111110을 AND 연산하여 attr의 첫 번째 비트만 0으로 설정되고 나머지 비트는 그대로 유지됨
    printf("attr: 0x%02x\n", attr); // attr의 값을 16진수 형식으로 출력 // attr의 값은 0b000001 01이므로 0x05로 출력됨 
    return 0; // 프로그램 종료
}
//2진법 0b00000001은 16진법으로 0x01, 2진법 0b00000110은 16진법으로 0x06, 2진법 0b00000111은 16진법으로 0x07, 2진법 0b00000101은 16진법으로 0x05입니다.
//attr 변수는 8비트 부호 없는 정수형 자료형인 uint8_t로 선언되어 있습니다. attr 변수는 비트 연산을 사용하여 특정 비트를 설정하거나 해제하는 데 사용됩니다. attr = attr ^ attr; 구문은 attr의 값을 자기 자신과 XOR 연산하여 0으로 초기화하는 역할을 합니다. 이후 attr = attr | 0b00000001; 구문은 attr의 첫 번째 비트를 1로 설정하여 0b00000001이 됩니다. 다음으로 attr = attr | (0b00000010 + 0b00000100); 구문은 attr의 두 번째와 세 번째 비트를 1로 설정하여 0b00000110이 됩니다. 마지막으로 attr = attr & (~0b00000001); 구문은 attr의 첫 번째 비트를 0으로 설정하여 0b00000110이 됩니다. 각 단계에서 printf 함수를 사용하여 attr의 값을 16진수 형식으로 출력합니다.